package com.rx.admin.modules.system.user.convert;  import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.rx.admin.common.result.PageResult; import com.rx.admin.modules.system.user.entity.SysUser; import com.rx.admin.modules.system.user.dto.UserCreateDTO; import com.rx.admin.modules.system.user.dto.UserUpdateDTO; import com.rx.admin.modules.system.user.vo.UserVO; import org.mapstruct.Mapper; import org.mapstruct.Mapping; import org.mapstruct.MappingTarget; import org.mapstruct.ReportingPolicy;  import java.util.List;  /**  * 鐢ㄦ埛瀵硅薄杞崲鍣紙MapStruct 缂栬瘧鏈熺敓鎴愬疄鐜帮級  * 缁熶竴绠＄悊 Entity 鈫?DTO 鈫?VO 鐨勮浆鎹㈤€昏緫  */ @Mapper(componentModel = "spring", unmappedTargetPolicy = ReportingPolicy.IGNORE)
@SuppressWarnings("null")
public interface UserConvert {      /** DTO 鈫?Entity锛堝垱寤烘椂锛?*/     SysUser toEntity(UserCreateDTO dto);      /** DTO 鈫?Entity锛堟洿鏂版椂锛屽拷鐣?null 鍊硷級 */     void updateEntity(@MappingTarget SysUser entity, UserUpdateDTO dto);      /** Entity 鈫?VO锛堣繑鍥炵粰鍓嶇锛屾帓闄?password锛?*/     @Mapping(target = "deptName", ignore = true)     @Mapping(target = "roleIds", ignore = true)     @Mapping(target = "roleNames", ignore = true)     UserVO toVO(SysUser entity);      /** MyBatis-Plus Page 鈫?PageResult */     default PageResult<UserVO> toPageResult(Page<SysUser> page) {         List<UserVO> voList = page.getRecords().stream()                 .map(this::toVO)                 .toList();         return PageResult.of(page.getTotal(), page.getCurrent(), page.getSize(), voList);     } }